# content_ajpm.py — 17호 고혈압성질환 사망 American Journal of Preventive Medicine(Elsevier, EM AJPM) Research Article의 Methods·Results(2026-11-14).
#   천 단위 쉼표(미국식), "Figure n" 표기, Methods에 IRB·"Statistical Analysis" 소제목·소프트웨어 버전. 수치는 numbers_htnd에서만(content_htnd 재사용), 주장 대조 assert는 content_htnd가 수행.
import content_htnd as C
from content_htnd import N, M, tci, ci, S43, S41, S44, S45, NCO, dW, BW, R4, RET, NALT, ret, wt, WN, sidos, _NC, VSP, VHYP, VP, _PPC, _per_s, _SE, CS, AC, A, SMR, NHYP, EXP_CHANCE
from content_htnd import SHT, TRT, AWR, OBE, MDM, ALC, WALK, MPA, FAC, BLS, IMS, OLD
def th(x, d=0): return f"{x:,.{d}f}"   # AJPM: 천 단위 쉼표
TITLE = "Excess hypertensive disease deaths in Busan, South Korea, persist after adjustment for district blood pressure care indicators"   # review 1회차(11/14): lasting·do not account for 과장 → 주모형 조정 후 지속(발견형)
assert ":" not in TITLE and TITLE != C.TITLE and "2011" not in TITLE and "229" not in TITLE and "standardi" not in TITLE.lower() and len(TITLE.split()) <= 25
KEYWORDS = "Hypertension; Mortality; Death certificates; Small-area analysis; Bayesian analysis; Republic of Korea"
assert 1 <= len(KEYWORDS.split("; ")) <= 7
SUP = {"methods": "Appendix Methods", "covariates": "Appendix Table 1", "datacheck": "Appendix Table 2", "specs": "Appendix Tables 3a-3d", "coding": "Appendix Tables 4a-4c", "reverse": "Appendix Table 5",
       "regions": "Appendix Table 6", "persistence": "Appendix Figure 1", "forest": "Appendix Figure 2"}
def sup(k): return SUP[k]
IRB = ("The Institutional Review Board of Hongik University approved the study on November 4, 2025 (7002340-202511-HR-012) and its continuing review on November 3, 2026 "
       "(7002340-202611-HR-040) and waived informed consent because only published aggregate statistics were used.")

METHODS = [
("Study Design and Data Sources",
 f"This ecological study used annual deaths from hypertensive diseases (ICD-10 codes I10-I13: essential hypertension and hypertensive heart, kidney, and heart and kidney disease) in 2011-2024 by district of residence from the national cause-of-death statistics of Statistics Korea, which cover all registered deaths [@web:kostat2026cause]. Data were extracted in November 2026. Districts were harmonized to {N['n_districts']} units with 2024 boundaries ({th(N['n_rows'])} district-years), with resident populations by 5-year age group as denominators [@web:mois2026population]; a duplicated 2023 population block and implausible 2021-2023 assistance counts in Changwon were corrected before modeling ({sup('methods')}). {IRB} Reporting follows the Strengthening the Reporting of Observational Studies in Epidemiology (STROBE) statement [@vonelm2007strengthening]."),
("Measures",
 "Expected deaths were obtained by indirect standardization: national age-specific death rates in eighteen 5-year groups up to 85 years or older were applied to each district's age structure each year and rescaled so that their national total equaled observed deaths [@inskip1983methods]. Observed over expected deaths gives the standardized mortality ratio (SMR). National trends were directly standardized to the 2015 population.",
 f"Twelve district characteristics were selected on the basis of the epidemiologic literature on blood pressure, its control, and hypertensive disease mortality [@lewington2002age; @ncdrisc2021worldwide; @park2016spatial], within the limits of annually available district series. Blood pressure care was represented by three indicators drawn from different populations, not a linked care cascade: the share of national health screening attendees with suspected hypertension on measured blood pressure among those not classified as under treatment, the treatment rate among adults with diagnosed hypertension, and awareness of one's own blood pressure; cardiometabolic risk by the screening shares of abdominal obesity and suspected diabetes and by high-risk drinking; physical activity by walking, moderate-or-higher-intensity physical activity, and public sports facilities per 100,000 population; and structure and access by the share receiving basic livelihood security benefits (means-tested public assistance), internal medicine specialists per 100,000, and households of older adults living alone. Survey indicators were district age-standardized rates among adults from the Community Health Survey [@kang2015korea]. Low-salt preference, surveyed only until 2019, was examined in a 2011-2019 sensitivity analysis. Five controls were forced into every model: urban population share, physician density, sex ratio, fiscal autonomy, and the share aged 80 years or older (because the oldest age group was open-ended). Sources, expected directions, and filled cells are in {sup('covariates')} and panel checks in {sup('datacheck')}. Covariates were standardized to 1 SD, and missing years were filled within districts."),
("Statistical Analysis",
 f"The negative binomial likelihood was chosen by the lower widely applicable information criterion (WAIC) of the forced-controls model. Models had an offset of log expected deaths, a Besag-York-Mollié 2 district effect on a contact graph of 593 neighboring district pairs with penalized-complexity priors [@riebler2016intuitive; @simpson2017penalising], and random-walk and independent year effects, fitted by integrated nested Laplace approximation [@rue2009approximate] (R-INLA 25.10.19) in R version 4.6.0 (R Foundation for Statistical Computing, Vienna, Austria) [@web:rcore2026]. Mortality rate ratios (MRRs) per 1 SD are reported with 95% credible intervals (CrIs); an association was credible when the interval excluded 1. Credible intervals were not adjusted for multiplicity; associations were exploratory and were assessed for sensitivity to model specification.",
 f"Sensitivity to covariate selection was assessed with 200 random covariate subsets (subset-stable: interval excluding 1 in at least 75% of subsets containing the characteristic). Structural checks were given priority: Knorr-Held type I-IV space-time interactions, of which types II and IV allow district-specific trends [@knorrheld2000bayesian], and a province-by-year effect. Subset-stable characteristics were split into district means and two-way-centered within-district deviations [@bell2015explaining]. Fourteen alternative specifications varied the likelihood, time effects, smoothing, lags, extreme values, and years ({sup('specs')}); further checks included a Spatial+-type adjustment [@dupont2022spatial], two comparison outcomes (transport accident deaths and people treated for infectious diseases), and negative-control exposures (hit-and-run accidents, a traffic culture index, and fires). Residual hot and cold spots had a posterior probability of a residual spatial rate ratio above 1 greater than 0.95 or less than 0.05, without correction for multiple comparisons. The variance of the linear predictor was partitioned into spatial, temporal, and covariate components, which covary and so are not proportions of explained variance.",
 f"Because deaths of people with hypertension may be certified to hypertensive disease or to heart failure, stroke, or ischemic heart disease [@snyder2014redistribution], the national share of circulatory deaths (I00-I99) certified as hypertensive was tracked, and the principal model was refitted with all circulatory deaths as the outcome, with and without the share of ill-defined causes (R00-R99) as a marker of certification quality ({sup('coding')}). Moderate-or-higher physical activity was credible opposite to the expected direction; the principal model was kept, and post hoc checks fitted it with the forced controls alone and without the other activity measures ({sup('reverse')}). Also added after results were seen were refits to circulatory deaths excluding hypertensive diseases, a forced-controls-only model to compare residual spatial rate ratios of Busan districts before and after the 12 characteristics, the same ratios after adding the ill-defined cause share, and an age-standardized comparison of hypertensive with circulatory mortality in Busan."),
]

RESULTS = [
("Deaths, Trends, and Certification",
 f"Over 2011-2024, {th(N['cases_total'])} deaths from hypertensive diseases occurred in {N['py']/1e6:.0f} million person-years; annual deaths rose from {th(N['cases_2011'])} to {th(N['cases_2024'])}, and the share at ages 85 years or older from {100*N['share85_2011']:.1f}% to {100*N['share85_2024']:.1f}% (Table 1). The directly age-standardized rate fell from {A[2011]:.1f} per 100,000 in 2011 to {A[2021]:.1f} in 2021, rose to {A[2022]:.1f} in 2022, and was {A[2024]:.1f} in 2024 (ratio 2024 to 2011, {N['asr_ratio']:.2f}), whereas that of all circulatory deaths fell from {AC[2011]:.1f} to {AC[2024]:.1f} (ratio {AC[2024]/AC[2011]:.2f}). The share of circulatory deaths certified as hypertensive rose from {100*CS[2011]:.1f}% in 2011 to {100*CS[2024]:.1f}% in 2024 (Figure 1)."),
("Geography",
 f"Moran's I was {N['moran_pooled']:.2f} for pooled log SMRs. Over the whole period, {N['n_hot']} districts were residual hot spots, mainly in {sidos(N['hot_by_sido'], 6)}; all {N['busan_n']} districts of Busan were hot spots, with residual spatial rate ratios of {N['busan_rr_main'][0]:.2f} to {N['busan_rr_main'][1]:.2f}. Cold spots numbered {N['n_cold']}, the largest number ({N['cold_by_sido']['서울시']}) in Seoul (Figure 2). The pooled SMR was {SMR['부산시']:.2f} in Busan, {SMR['울산시']:.2f} in Ulsan, and {SMR['서울시']:.2f} in Seoul. In window-specific models, {N['hot_all_windows']} districts were hot spots in all three windows, {_SE} of them in the southeastern provinces and cities, and Kendall's W for annual district rankings was {N['kendall_W']:.2f} ({sup('persistence')})."),
("District Characteristics",
 f"Adding the {NHYP} characteristics changed WAIC from {th(N['waic_forced'],1)} to {th(N['waic_main'],1)}. Mortality was lower with more internal medicine specialists ({ci(IMS)}) and, opposite to expectation, higher with more moderate-or-higher physical activity ({ci(MPA)}; lower bound above 1 before rounding, posterior probability of an MRR above 1, {N['main'][MPA]['P_gt1']:.3f}) (Table 2). The other 10 characteristics, including suspected hypertension on screening ({ci(SHT)}), treatment among diagnosed adults ({ci(TRT)}), and blood pressure awareness ({ci(AWR)}), were not credibly associated. Among the forced controls, mortality was lower with a higher urban population share ({ci('urban_population_share')}), fiscal autonomy ({ci('fiscal_independence')}), and share aged 80 years or older ({ci('pop80_share')}). Of the negative-control exposures, fires were credibly associated ({_NC('fires_per_10000')}), whereas hit-and-run accidents ({_NC('hit_and_run_rate')}) and the traffic culture index ({_NC('traffic_culture_index')}) were not ({sup('specs')}). Of the summed variance components, structured spatial variation contributed {100*VSP:.0f}% and the {NHYP} characteristics {100*VHYP:.0f}%."),
("Robustness",
 f"Only moderate-or-higher physical activity was subset-stable (credible in {100*N['mv'][MPA]['cred_frac']:.0f}% of subset fits); internal medicine specialists were credible in {100*N['mv'][IMS]['cred_frac']:.0f}%. Models allowing district-specific trends fitted better (ΔWAIC {th(dW('KH_typeII'))} for type II and {th(dW('KH_typeIV'))} for type IV), and in them neither association was credible (type II: {tci(S43('KH_typeII', MPA))} for physical activity and {tci(S43('KH_typeII', IMS))} for specialists), nor with province-by-year effects; basic livelihood recipients became credible in the type II model ({tci(S43('KH_typeII', BLS))}) ({sup('forest')}). Physical activity was not credible in any calendar window and was credible in {RET[MPA][0]} of {NALT} alternative specifications, and specialists in {ret(IMS)[0]} of {NALT} (classified from unrounded bounds). Basic livelihood recipients were credible in 2011-2015 and 2016-2019 but not in 2020-2024. For physical activity, the within-district component was credible ({tci(BW(MPA, 'within'))}) and the between-district component was not ({tci(BW(MPA, 'between'))}); the association persisted with the forced controls alone ({tci(R4(MPA))}) and without the other activity measures ({sup('reverse')}), and region-specific slopes produced essentially no improvement in WAIC (ΔWAIC {N['s50_region_dwaic'][MPA]:.1f}), with the region-specific estimate excluding 1 only in the capital region ({tci(N['s50_region'][(MPA, 'Capital')][:3])}) ({sup('regions')}). Posterior predictive 95% intervals covered {_PPC:.1f}% of district-years."),
("Certification Checks",
 f"With all circulatory deaths as the outcome, district residual spatial rate ratios correlated with those for hypertensive diseases (Spearman ρ {N['rr_main_broad_rho']:.2f}), and all {N['busan_n']} Busan districts remained hot spots ({N['busan_rr_broad'][0]:.2f} to {N['busan_rr_broad'][1]:.2f}; Figure 2); with circulatory deaths excluding hypertensive diseases, they were again all hot spots ({N['busan_rr_nonhtn'][0]:.2f} to {N['busan_rr_nonhtn'][1]:.2f}). The ratio of the hypertensive to the circulatory SMR was {N['smr_ratio'][True]:.2f} in Busan and {N['smr_ratio'][False]:.2f} elsewhere. Ill-defined causes accounted for {100*N['busan_illdef']:.1f}% of all deaths in Busan and {100*N['rest_illdef']:.1f}% elsewhere. With the ill-defined cause share added, which was itself associated with fewer hypertensive deaths ({tci(S45('Z1_illdefined', 'ill_defined_death_share'))}), the average residual spatial rate ratio of Busan districts was {N['busan_ill']['htnd'][2]:.2f} for hypertensive diseases ({N['busan_ill']['htnd'][3]} hot spots) and {N['busan_ill']['circ'][2]:.2f} for all circulatory deaths ({N['busan_ill']['circ'][3]} hot spots), compared with {N['busan_mean_rr']['RR_main']:.2f} and {N['busan_broad_mean']:.2f} without it. With the forced controls only, the average for Busan districts was {N['busan_mean_rr']['RR_forced']:.2f}, and after the 12 characteristics were added, {N['busan_mean_rr']['RR_main']:.2f}. For transport accident deaths, basic livelihood recipients were also credibly associated ({tci(NCO('TRANS', BLS))}) ({sup('specs')}). Low-salt preference in 2011-2019 was not associated ({tci(S45('Z5_low_salt_2011_2019', 'low_salt_preference_rate'))}) ({sup('coding')})."),
]

if __name__ == "__main__":
    import re
    f = lambda t: len(re.sub(r"\[@[^\]]+\]", "", t).split())
    for x in METHODS + RESULTS: print("##", x[0], sum(f(p) for p in x[1:]))
    print("M", sum(f(p) for x in METHODS for p in x[1:]), "R", sum(f(p) for x in RESULTS for p in x[1:]))
def C0_TITLE_ABSENT(txt): return C.TITLE not in txt   # 이전 제목이 산출물에 없음
